vec3 render(vec2 coord)
{
    vec2 uv = (coord * 2. - iResolution.xy) / iResolution.x;

    float freq = resonant_frequnecy(iTime);
    float bar_width = 60. / freq;

    return mix(
        vec3(.01, .03, .06),
        pow(vec3(1, .75, 0.4), vec3(.5 / bar_width)),
        float(abs(uv.x) < bar_width) * float(abs(uv.y) < .01)
    );
}

vec3 view_transform(vec3 col)
{
    // OETF (Linear BT.709 I-D65 to sRGB 2.2)
    return pow(clamp(col, 0., 1.), vec3(1. / 2.2));
}

void mainImage(out vec4 frag_col, in vec2 frag_coord)
{
    frag_col = vec4(view_transform(render(frag_coord)), 1);
}

const float TAU = 6.283185307179586476925286767;

float resonant_frequnecy(float time)
{
    return exp2(mix(
        log2(80.),
        log2(3000.),
        1. - (cos(TAU * .05 * time) * .5 + .5)
    ));
}



/*__________ hash function collection _________*/
// sources: https://nullprogram.com/blog/2018/07/31/
//          https://www.shadertoy.com/view/WttXWX

uint triple32(uint x)
{
    x ^= x >> 17;
    x *= 0xed5ad4bbU;
    x ^= x >> 11;
    x *= 0xac4c1b51U;
    x ^= x >> 15;
    x *= 0x31848babU;
    x ^= x >> 14;
    return x;
}

// uint -> uint

uint hash(uint v)
{
    return triple32(v);
}

uint hash(uvec2 v)
{
    return triple32(v.x + triple32(v.y));
}

uint hash(uvec3 v)
{
    return triple32(v.x + triple32(v.y + triple32(v.z)));
}

uint hash(uvec4 v)
{
    return triple32(v.x + triple32(v.y + triple32(v.z + triple32(v.w))));
}

// int -> uint

uint hash(int v)
{
    return triple32(uint(v));
}

uint hash(ivec2 v)
{
    return triple32(uint(v.x) + triple32(uint(v.y)));
}

uint hash(ivec3 v)
{
    return triple32(uint(v.x) + triple32(uint(v.y) + triple32(uint(v.z))));
}

uint hash(ivec4 v)
{
    return triple32(uint(v.x) + triple32(uint(v.y) + triple32(uint(v.z) + triple32(uint(v.w)))));
}

// float -> uint

uint hash(float v)
{
    return triple32(floatBitsToUint(v));
}

uint hash(vec2 v)
{
    return triple32(floatBitsToUint(v.x) + triple32(floatBitsToUint(v.y)));
}

uint hash(vec3 v)
{
    return triple32(floatBitsToUint(v.x) + triple32(floatBitsToUint(v.y) + triple32(floatBitsToUint(v.z))));
}

uint hash(vec4 v)
{
    return triple32(floatBitsToUint(v.x) + triple32(floatBitsToUint(v.y) + triple32(floatBitsToUint(v.z) + triple32(floatBitsToUint(v.w)))));
}

// any -> int
#define hashi(v) int(hash(v))

// any -> float
#define hashf(v) (float(hash(v)) / 4294967295.)

const float DECAY = 20.;

float samp_to_time(int samp)
{
    return float(samp) / iSampleRate;
}

int time_to_samp(float time)
{
    return int(floor(time * iSampleRate));
}

float pinkish_noise(int samp, int channel)
{
    return (
        hashf(ivec2(samp + 0, channel))
        + hashf(ivec2(samp + 1, channel))
        + hashf(ivec2(samp + 2, channel))
    )
    / 3.;
}

vec2 render_audio(int samp)
{
    // stereo pinkish noise
    vec2 v = vec2(
        pinkish_noise(samp, 0),
        pinkish_noise(samp, 1)
    );

    // mono-ize a little
    v = mix(v, vec2(dot(v, vec2(.5))), .7);

    // gain and return
    return .1 * v;
}

// https://www.desmos.com/calculator/vakt3kgbqa
vec2 render_audio_filtered(int samp, float resonant_freq)
{
    // distance between each pulse which ultimately depends on the length
    // of the string.
    float pulse_dist = .5 / resonant_freq;

    // convolve
    vec2 v = vec2(0);
    for (int i = 0; i < 32; i++)
    {
        float time_offs = pulse_dist * float(i);
        int samp_offs = time_to_samp(time_offs);

        float alternate_sign = (i % 2 == 0) ? 1. : -1.;
        float decay_fac = exp(-time_offs * DECAY);

        v += render_audio(samp - samp_offs) * alternate_sign * decay_fac;
    }
    return v;
}

vec2 mainSound(int samp, float time)
{
    return render_audio_filtered(samp, resonant_frequnecy(time));
}
